MATCH (a:Airport)
WHERE EXISTS {
  MATCH (fa1:FlightAccident)-[:departsFrom]->(a)
  WHERE fa1.name = "Pan Am Flight 217" OR "Pan Am Flight 217" IN fa1.aliases
}
OR EXISTS {
  MATCH (fa2:FlightAccident)-[:destinedFor]->(a)
  WHERE fa2.name = "Avianca Flight 052" OR "Avianca Flight 052" IN fa2.aliases
}
RETURN count(DISTINCT a) AS airport_count

MATCH (acc:FlightAccident)
WHERE EXISTS {
    MATCH (acc)-[:involves]->(m:AircraftModel)
    WHERE m.name CONTAINS 'L-410 Turbolet'
} OR EXISTS {
    MATCH (acc)-[:departsFrom]->(a:Airport)
    WHERE a.name = 'Ramón Villeda Morales International Airport'
}
RETURN DISTINCT acc.name AS AccidentName
